class UniqueResource {
    int* ptr;
public:
    UniqueResource(int size) : ptr(new int[size]) {}
    ~UniqueResource() { delete[] ptr; }

    // Prevent copying (ensures single ownership)
    UniqueResource(const UniqueResource&) = delete;

    // Prevent copy assignment
    UniqueResource& operator=(const UniqueResource&) = delete;

    // Prevent move assignment (if resource transfer is disallowed)
    UniqueResource& operator=(UniqueResource&&) = delete;

    // Prevent default construction
    UniqueResource() = delete;
};
